Method.Implementation:
$$$TRACE("Inside  Method OnGetConnections")
Do ##super(.pArray,pItem)
If pItem.GetModifiedSetting("TargetConfigNames",.tValue) {
	For i=1:1:$L(tValue,",") { Set tOne=$ZStrip($P(tValue,",",i),"<>W")  Continue:""=tOne  Set pArray(tOne)="" }
}

#dim pStat As %Status=$$$OK set tQueryStagingProcessed="update "_..DBSchema_".STAGING set Processed ='"_status_"' where EVENT_ID="_eventID
try { set tSCStagingProcessed=..Adapter.SetAutoCommit(1) $$$TRACE(" Query to Execute : "_tQueryStagingProcessed) set tSCStagingProcessed=..Adapter.ExecuteUpdate(.tNumRowsAffectedStagingProcessed,tQueryStagingProcessed) $$$TRACE(" SUCCESS Updating Processed Flag to "_status_" in Staging : "_tSCStagingProcessed)
} CATCH err { $$$LOGERROR( "Error while Updating Processed Flag to "_status_" in Staging " _ err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code) set tSCStagingProcessed = $$$ERROR( "SQLError:Error while Updating Processed Flag to "_status_"in Staging " _ err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code) }
return $$$OK


// Filtering logic Starts

	//Check if Order Date less than 01/01/2012 then filter it and Set processed as Y
	Set extractSQLDate = $EXTRACT(resultRecord.GetData(4),0,10)
	$$$TRACE("  Exact SQL Date  : "_extractSQLDate)
	set DiffADate =  $System.SQL.DATEDIFF("d","01/01/2012",extractSQLDate)
	$$$TRACE("  Diff days  : "_DiffADate)
	if DiffADate <= 0
	{
	    //Setting Processed Flag as "Y" in Staging
	    $$$TRACE(" Order Date less than 01/01/2012" )
		set upStatus = ..UpdatePreviousProcessed("Y",resultRecord.GetData(2))
		//**TODO** - Add code to continue to next record in For loop
		return 1	// Record filtered
	}

	 $$$TRACE(" Before Drug Ncid  "  )
	//Check if it is a Text Order
	if $L(resultRecord.GetData(9)) = 0
	{
		//Setting Processed Flag as "Y" in Staging
	    $$$TRACE(" Order is a Text order since Drug Ncid is Null "  )
		set upStatus = ..UpdatePreviousProcessed("Y",resultRecord.GetData(2))
		//**TODO** - Add code to continue to next record in For loop	
		return 1
	}

	$$$TRACE(" Before Order Status  "  )
	// Check if Order Status is either Discontinued or Error 
	if (resultRecord.GetData(6) = 1524) || (resultRecord.GetData(6) = 69074)
	{
		//Setting Processed Flag as "Y" in Staging
	    $$$TRACE(" Order Status Ncid("_resultRecord.GetData(6)_") is either 1524(Discontinued) or 69074 (Error) "  )
	    set isdiscontinuedOrError = 0 // Setting flag which is used in updating ProcessedOrder Table
		set upStatus = ..UpdatePreviousProcessed("Y",resultRecord.GetData(2))
		//**TODO** - Add code to continue to next record in For loop
		return 1	
	}

	return 0

#dim pStat As %Status=$$$OK
$$$TRACE("Inside Method UpdateProcessedOrders")

$$$TRACE("isPreProcessed"_..isPreProcessed)
//Check if it is PreProcessed  orders then update the ProcessedOrders Table
if ..isPreProcessed = 0 
{
	$$$TRACE("editVersion"_..editVersion)
	set ..editVersion = ..editVersion + 1
	$$$TRACE("editVersion"_..editVersion)
	set tQueryProcessedOrders="update "_..DBSchema_".PROCESSEDORDERS set Edit_Version='"_..editVersion_"' where EVENT_ID="_eventID


	 	try
	 	{
		 	set tSCProcessedOrders=..Adapter.SetAutoCommit(1)
			$$$TRACE("  Query to Execute : "_tQueryProcessedOrders)
	 		set tSCProcessedOrders=..Adapter.ExecuteUpdate(.tNumRowsAffectedProcessedOrders,tQueryProcessedOrders) 
	 		$$$TRACE("  SUCCESS Updating PROCESSEDORDERS tables VersionId to "_..editVersion_" - "_tSCProcessedOrders)

	 	}
     	CATCH err 
     	{
	     	$$$LOGERROR( "Error while PROCESSEDORDERS tables VersionId to "_..editVersion_" - "  _ err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)
         	set tSCProcessedOrders = $$$ERROR( "SQLError:Error while Updating PROCESSEDORDERS tables VersionId to "_editVersion_" - "  _ err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)	    
      	}

}
else
{
   $$$TRACE("Inside new column for ProcessedOrder")

	set tQueryProcessedOrders="insert into "_..DBSchema_".PROCESSEDORDERS values ("_eventID_",0,"_pResp.PID02AltPatientID_",null,"_pResp.RXO0101RequestCode_",'Y',null)"


	 	try
	 	{
		 	set tSCProcessedOrders=..Adapter.SetAutoCommit(1)
			$$$TRACE("  Query to Execute : "_tQueryProcessedOrders)
	 		set tSCProcessedOrders=..Adapter.ExecuteUpdate(.tNumRowsAffectedProcessedOrders,tQueryProcessedOrders) 
	 		$$$TRACE("  SUCCESS inserting new row in "_..DBSchema_".PROCESSEDORDERS - "_tSCProcessedOrders)

	 	}
     	CATCH err 
     	{
	     	$$$LOGERROR( "Error while inserting new row in "_..DBSchema_".PROCESSEDORDERS "_..editVersion_" - "  _ err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)
         	set tSCProcessedOrders = $$$ERROR( "SQLError:Error while inserting new row in "_..DBSchema_".PROCESSEDORDERS "_editVersion_" - "  _ err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)	    
      	}
}

      	return $$$OK

	$$$TRACE("Inside Method ProcessMedOrderDb")
	$$$TRACE("DBSchema :"_..DBSchema)

	#dim tSC As %Status=$$$OK
	#dim tSCProcessedOrd As %Status=$$$OK
	#dim tSCStagingProcessed As %Status=$$$OK

	set pResponse=##class(IHC.ITF.Response.MedOrderDbResponse).%New()


	set tQuery="select * from "_..DBSchema_".STAGING where Processed='P'" //Actual code
	set tResult = ..ProcessMainQuery(tQuery)
	//$$$TRACE("  After ProcessMainQuery method ")

	//set tQuery ="select * from "_..DBSchema_".STAGING where EVENT_ID=?" // Testing code
	//set tResult = ..ProcessQuery(tQuery,3736543532)

	set RecordCount = 0

	// Process each record got from Staging
	while tResult.Next() 
	{
		set RecordCount = RecordCount+1
		$$$TRACE("  ************** Processing Record Number : "_RecordCount)



		//if RecordCount > 5000
		//{
		//	QUIT
		//}

		$$$TRACE("  Processing Event_ID from Staging: "_tResult.GetData(2))
		set ..isPreProcessed = 1 // Resetting the Flag value for the next record
	    set ..editVersion = 0 // Resetting the  value for the next record
	    set ..SIGText=""  // Resetting the  value for the next record 

	//Check record with Processed Orders
	set tQueryProcessedOrd="select * from "_..DBSchema_".PROCESSEDORDERS where EVENT_ID=?"
	set tResultProcessedOrd = ..ProcessQuery(tQueryProcessedOrd,tResult.GetData(2))

	// If entry exists in Processed Orders, Set Processed flag as "Y"
		if tResultProcessedOrd.Next() 
		{
			$$$TRACE("  EventID  : ["_tResultProcessedOrd.GetData(1)_"] present in ProcessedOrders table")
			set ..isPreProcessed = 0 //0 means true - This is a flag to identify if the record is pre processed. this will be used below in ORC segment

		    $$$TRACE(" EditVersion in Staging : "_tResult.GetData(3)_" and  EditVersion in ProcessedOrders : "_tResultProcessedOrd.GetData(2))
		    set ..editVersion = tResultProcessedOrd.GetData(2) // Setting this value to use in method to update ProcessedOrder table if necessary 

		    //Check If the EditVersion in Staging is less than or equal to the EditVersion of ProcessedOrders, then row is already processed
		    if tResult.GetData(3) <= tResultProcessedOrd.GetData(2)
		    {
		    $$$TRACE(" EditVersion in Staging is less than or equal to the EditVersion of ProcessedOrders ")
		    //Setting Processed Flag as "Y" in Staging
	//TODO remove	    set upStatus = ..UpdatePreviousProcessed("Y",tResultProcessedOrd.GetData(1))

		    //**TODO** - Add code to continue to next record in For loop
		    }

		}
		//**TODO** - Remove below else block since if control reaches this point we need to set proccess flag to "P"
		else //  If entry does not exists in Processed Orders, Set Processed flag as "P" to indicate the record is in Process
		{
			$$$TRACE("  EventID  : ["_tResult.GetData(2)_"] Not present in ProcessedOrders table")
		    //Setting Processed Flag as "P" in Staging
	// TODO remove		set upStatus = ..UpdatePreviousProcessed("P",tResult.GetData(2))
		}


		//Do Filtering Logic

		set isfiltered = ..FilterMessages(tResult)

		if isfiltered = 1
		{
			$$$TRACE(" Record Filtered.. Proceding to next record")
		  	set filterupdateStatus = ..UpdatePreviousProcessed("Y",tResultProcessedOrd.GetData(1))
		  	CONTINUE
		}


		// Create Hl7 fields

		set pResp=##class(IHC.ITF.Response.ProcessMedOrder).%New()

		set pResp.EventID = tResult.GetData(2) // Set event id , for testing

		//Process MSH Segment
		Do ..ProcessMSHSegment(pResp)

		//Process PID Segment
		Do ..ProcessPIDSegment(pResp,tResult)

		//Process ORC Segment
		Do ..ProcessORCSegment(pResp,tResult)

		//Process ORM Segment
		Do ..ProcessRXOSegment(pResp,tResult)

		//Process NTE Segment
		Do ..ProcessNTESegment(pResp,tResult)

		//Process RXR Segment
		Do ..ProcessRXRSegment(pResp,tResult)


		$$$TRACE(" MSH03 Value : "_pResp.MSH03SendingApp)
		$$$TRACE(" PID02 Value : "_pResp.PID02AltPatientID)
		$$$TRACE(" ORC01 Value : "_pResp.ORC01OrderControl)
		$$$TRACE(" ORC02.1 Value : "_pResp.ORC0201UniquePlacerNo)
		$$$TRACE(" RXO01.1 Value : "_pResp.RXO0101RequestCode)
		$$$TRACE(" RXO01.2 Value : "_pResp.RXO0102CodeDescription)
	    $$$TRACE(" RXO3 Value : "_pResp.RXO03RequestAmountMaximum)
	    $$$TRACE(" RXO4 Value : "_pResp.RXO04RequestGiveUnits)
	    $$$TRACE(" NTE02 Value : "_pResp.NTE02SourceComment)
	    $$$TRACE(" RXR01 Value : "_pResp.RXR01Route)

		//Update ProcessedOrders Table
	//TODO remove	set upStatusFinal2 = ..UpdateProcessedOrders(tResult.GetData(2),pResp)


        // Final update of Processed Flag as "Y
      //TODO remove  set upStatusFinal = ..UpdatePreviousProcessed("Y",tResult.GetData(2))


		set ..isPreProcessed = 1 // Resetting the Flag value for the next record
		set ..editVersion = 0 // Resetting the value for the next record

	    //Insert the response for this record into the Main Response's List
		do pResponse.ResponseList.Insert(pResp)
		$$$TRACE(" EMPI of Response Added to List "_pResponse.ResponseList.GetNext().PID02AltPatientID)
    }

	quit pResponse

$$$TRACE(" ProcessORCSegment Start ")
#dim tSCAList As %Status=$$$OK



// Set ORC01

if (resultRecord.GetData(6) = 1555) && (..isPreProcessed = 1)
{
	set pResp.ORC01OrderControl = "NW"
}
elseif (resultRecord.GetData(6) = 1555) && (..isPreProcessed = 0)
{
	set pResp.ORC01OrderControl = "XO"
}
elseif resultRecord.GetData(6) = 1524
{
	set pResp.ORC01OrderControl = "DC"
}

//Set ORC2.1

set tQueryAList="select * from "_..DBSchema_".A_LIST where EVENT_ID=?"
set tResultAList = ..ProcessQuery(tQueryAList,resultRecord.GetData(2))

// If entry exists in A_LIST Orders, Append "A" to Event id and set in ORC2.1
if tResultAList.Next() 
{
	set pResp.ORC0201UniquePlacerNo = "A"_resultRecord.GetData(2)
}
else
{
	set pResp.ORC0201UniquePlacerNo = resultRecord.GetData(2)
}


set pResp.ORC0202PlacerAppId = ""

//IF Sort_NCID =  521051182 AND ORC.01 is set to ‘NW’ THEN ‘H’ ELSE ‘O’

if (resultRecord.GetData(25) = 521051182) && (pResp.ORC01OrderControl = "NW")
{
	set pResp.ORC05OrderStatus = "H"
}
else
{
	set pResp.ORC05OrderStatus = "O"
}




Do ..setORC07QuantityTiming(pResp,resultRecord)
//set pResp.ORC07QuantityTiming = 	

//Date format we get from DB is 2015-10-14 06:00:00.0 if no time is given in DB

set SQLDate = $REPLACE(resultRecord.GetData(4),"-","") //Remove the "-" {20151014 06:00:00.0}
set SQLDate = $REPLACE(SQLDate," ","") // Remove the space {2015101406:00:00.0}
set SQLDate = $REPLACE(SQLDate,":","") // Remove the ":" {201510140600:00.0}
Set SQLDate = $EXTRACT(SQLDate,0,12) // {201510140600}
Set JustDate = $EXTRACT(SQLDate,0,8) // {20151014}

//We are going to check if time is 06:00.it means it is the default from DB and we going to change it to 00:00
if SQLDate = JustDate_"0600"
{
	set pResp.ORC09TransactionDate = JustDate_"0000"

}
else
{
	set pResp.ORC09TransactionDate = SQLDate
}



//*** TODO *** webservice call(MSPR) to populate the value 
set pResp.ORC12OrderingProvider = resultRecord.GetData(7)

$$$TRACE(" ProcessORCSegment End ")
return $$$OK

$$$TRACE(" ProcessRXOSegment Start ")
#dim tSCRXO01 As %Status=$$$OK
#dim tSCSynID As %Status=$$$OK

//Set RXO1.1
//Check if entry exsists for Drug_Ncid in H2TRANSLATOR. if so copy the source_id from H2TRANSLATOR else check processed orders-
//-if record exists in Processed orders copy the OriginalSynID else leave the field blank

set tQueryRXO01="select * from "_..DBSchema_".H2TRANSLATOR where NCID=?"
set tResultRXO01 = ..ProcessQuery(tQueryRXO01,resultRecord.GetData(9))

// If entry exists in H2TRANSLATOR, copy the source_id from H2TRANSLATOR to ORM1.1 and NCID_txt to RXO1.2
if tResultRXO01.Next() 
{
	$$$TRACE(" Matching Record Exists in H2TRANSLATOR")
	set pResp.RXO0101RequestCode = tResultRXO01.GetData(2)
	set pResp.RXO0102CodeDescription = tResultRXO01.GetData(8) //Setting RXO1.2 here itself
	set pResp.RXO0103CodeMethod = tResultRXO01.GetData(4)
}
elseif ..isPreProcessed = 0 //check processed orders exists for the record. If so copy the OriginalSynID
{
	$$$TRACE(" Matching Record Exists in PROCESSEDORDERS")

	set tQuerySynID="select * from "_..DBSchema_".PROCESSEDORDERS where EVENT_ID=?"
	set tResultSynID = ..ProcessQuery(tQuerySynID,resultRecord.GetData(2))

// If entry exists in PROCESSEDORDERS, copy the OriginalSynID from PROCESSEDORDERS to ORM1.1 
	if tResultSynID.Next() 
	{
		set pResp.RXO0101RequestCode = tResultSynID.GetData(5)

	}

}
else
{
	$$$TRACE(" NO Matching Record in either H2TRANSLATOR or PROCESSEDORDERS")
	set pResp.RXO0101RequestCode = ""
}

//Set ORM1.2
//Check if ORM1.2 is already set in above process for ORM1.1. if not we need to do the HDD call for NCID to REP

//$$$TRACE("Before HDD call")
//Do ..DoHDDToRep(resultRecord.GetData(9), 2000)
//$$$TRACE("After HDD call")
if $L(pResp.RXO0102CodeDescription) = 0
{
	set pResp.DrugNcid = resultRecord.GetData(9) // Setting this value to do NCIDToRep in Bpl as we are not able to do NCIDToRep here

}

//Set ORM1.3
if $L(pResp.RXO0103CodeMethod) = 0
{
	set pResp.RXO0103CodeMethod = "M"
}

set pResp.RXO02RequestAmountMinimum = resultRecord.GetData(13)
set pResp.RXO03RequestAmountMaximum = resultRecord.GetData(14)

$$$TRACE(" Min : "_resultRecord.GetData(13))
$$$TRACE(" Max : "_resultRecord.GetData(14))
$$$TRACE(" ReqUnit : "_resultRecord.GetData(15))

$$$TRACE(" Length Min : "_$L(resultRecord.GetData(13))) 
$$$TRACE(" Length Max : "_$L(resultRecord.GetData(14))) 
$$$TRACE(" Length ReqUnit : "_$L(resultRecord.GetData(15)))

//Set ORM1.4. if both min and max amount are NOT null and only Req units ae null then set 91717 for ORM1.4
if ($L(resultRecord.GetData(13)) '= 0) && ($L(resultRecord.GetData(14)) '= 0) && ($L(resultRecord.GetData(15)) = 0)
{
	$$$TRACE(" Inside minmax condition")
	set pResp.RXO04RequestGiveUnits = "91717"	
}
else
{
	$$$TRACE(" Inside minmax Else condition")
	set pResp.RXO04RequestGiveUnits = resultRecord.GetData(15)
}

set pResp.RXO09AllowSubstitutions = resultRecord.GetData(24)
set pResp.RXO11ReqDispenseAmt = resultRecord.GetData(21)
set pResp.RXO12ReqDispenseUnits = resultRecord.GetData(22)
set pResp.RXO13NoOfRefills = resultRecord.GetData(23)


$$$TRACE(" ProcessRXOSegment End ")
return $$$OK

$$$TRACE(" ProcessNTESegment Start ")
set pResp.NTE01SetID = "1"
set pResp.NTE02SourceComment = "O"

$$$TRACE(" Comment : "_resultRecord.GetData(26))
$$$TRACE(" SIGText in NTE : "_..SIGText)
set ReplacedComment =""

if $L(resultRecord.GetData(26)) '= 0
{
	set ReplacedComment = resultRecord.GetData(26)
	set ReplacedComment = $REPLACE(ReplacedComment,$C(13,10),"~") //Replace a two-character sequence of Chr(13) and Chr(10) with '~'
	set ReplacedComment = $REPLACE(ReplacedComment,$C(10),"~") //Replace remaining Chr(10) with '~'
	set ReplacedComment = $REPLACE(ReplacedComment,$C(92),"\E\") //Replace Chr(92) with '\E\'
	set ReplacedComment = $REPLACE(ReplacedComment,"|",":") //Replace all '|' with ':'
	set ReplacedComment = $REPLACE(ReplacedComment,"^"," ") //Replace all '^' with ' '

	$$$TRACE(" Final Replaced Comment : "_ReplacedComment)
}

$$$TRACE(" resultRecord.GetData(26): "_resultRecord.GetData(26))


//set NTE03Comment

if ($L(resultRecord.GetData(26)) = 0) && ($L(..SIGText)= 0) //Medication name only ( Staging.Comment and SIGText is empty) 
{
	$$$TRACE(" Inside 1")
	set pResp.NTE03Comment = "Ordered as: "_pResp.RXO0102CodeDescription //Add Medication name in Bpl from RXO1.2 ( through HDD)
}

elseif ($L(resultRecord.GetData(26)) '= 0) && ($L(..SIGText)= 0) //Medication name and Comment (Staging.Comment not empty and SIGText is empty)
{
	$$$TRACE(" Inside 2")
	set pResp.NTE03Comment = "Ordered as: "_pResp.RXO0102CodeDescription_"~"_ReplacedComment //Adding Medication name(RXO1.2) after "Ordered as:" in Bpl from RXO1.2 ( through HDD)
}

elseif ($L(resultRecord.GetData(26)) '= 0) && ($L(..SIGText)> 0)  //Medication name, SIG, and Comment (Staging.Comment not empty and SIGText not empty)
{
	$$$TRACE(" Inside 3")
	set pResp.NTE03Comment = "Ordered as: "_pResp.RXO0102CodeDescription_"~"_..SIGText_"~"_ReplacedComment //Adding Medication name(RXO1.2) after "Ordered as:" in Bpl from RXO1.2 ( through HDD)
}

elseif ($L(resultRecord.GetData(26)) = 0) && ($L(..SIGText)> 0)  //Medication name and SIG (Staging.Comment is empty and SIGText not empty)
{
	$$$TRACE(" Inside 4")
	set pResp.NTE03Comment = "Ordered as: "_pResp.RXO0102CodeDescription_"~"_..SIGText //Adding Medication name(RXO1.2) after "Ordered as:" in Bpl from RXO1.2 ( through HDD)
}
else
{
	$$$TRACE(" Inside else")
	set pResp.NTE03Comment = "Ordered as: "_pResp.RXO0102CodeDescription_"~"_ReplacedComment
}

$$$TRACE(" ProcessNTESegment End ")
return $$$OK


	$$$TRACE("Inside Method setORC07QuantityTiming")

	#dim FreqAbstSC As %Status=$$$OK
	#dim FreqTranstSC As %Status=$$$OK
	#dim FreqTranstResult As %Status=$$$OK
	#dim FreqconversionSC As %Status=$$$OK
	#dim FreqConversionResult As %Status=$$$OK
	set isConvertToText =1
	set isConverstionRuleApplied = 0 // 0 is false
	set FreqText = ""
	set PrnFlag = "N"

	$$$TRACE("  Event ID : "_resultRecord.GetData(2))
	set FreqAbstOrderCount=..GetFrequencyTableRowCount(resultRecord.GetData(2))

	$$$TRACE("  FREQUENCY_ABSTRACT table Rowcount : "_FreqAbstOrderCount)




	// Getting records from FREQUENCY_ABSTRACT table 

	set FreqAbstQuery="select * from "_..DBSchema_".FREQUENCY_ABSTRACT where EVENT_ID=?"
	set FreqAbstResult = ..ProcessQuery(FreqAbstQuery,resultRecord.GetData(2))



	do FreqAbstResult.Next()
	//Text will be transferred to Cerner when:
    //  1. There is more than 1 row of frequencies for the order - OR –
    //  2. There is only 1 frequency, but it is not a named frequency - OR –
    //  3. There is only one frequency and it is named, but cannot be translated to a Cerner code.


	if FreqAbstOrderCount = 0    // if no records 
	{
		set isConvertToText = 0
		set pResp.ORC07QuantityTiming = "" //Scenario 1 - No Frequency_Abstract rows. The case is simple; Timing/Quantity is Null in the ORC segment.
		return $$$OK
	}
	$$$TRACE("  FreqAbstResult.GetData(4) : "_FreqAbstResult.GetData(4))

	// Check if only one 1 row exists in FREQUENCY_ABSTRACT table 
	if FreqAbstOrderCount > 1    
	{
		set isConvertToText = 0
	}
	elseif $L(FreqAbstResult.GetData(4)) = 0 // Check if Named frequencey is empty 
	{
		set isConvertToText = 0
	} 
	else
	{

		// Check if Named Frequency NCID can be translated to Cerner Code
		set FreqTranstQuery="select * from "_..DBSchema_".FREQUENCY_TRANSLATION where NCID=?" 
		set FreqTranstResult = ..ProcessQuery(FreqTranstQuery,FreqAbstResult.GetData(4))


		if FreqTranstResult.Next()
		{
			if FreqTranstResult.GetData(5) = "N"
			{
				set isConvertToText = 0
			}
		}


	}

	$$$TRACE("  isConvertToText : "_isConvertToText)

	set NamedFrequencyNCIDValue = FreqAbstResult.GetData(4) // This variable is needed as we need to manipulate it in CoversionRules logic below and use in Scenario 2.1

	//Do Conversion Rules - Start
	if (isConvertToText = 0) && (FreqAbstOrderCount = 1) //if need to convert to text and only one Frequency_Abstract row
	{
		$$$TRACE(" Trying to apply Conversion rules ")

		if FreqAbstResult.GetData(12) = "67655" // How_Often_Day_Week_ncid = 67655 (“every”), then copy value of Day_Of_Week_ncid into Named_Frequency_ncid value.
		{
			$$$TRACE(" How_Often_Day_Week_ncid = 67655 ")
			set NamedFrequencyNCIDValue = FreqAbstResult.GetData(10)
			set isConverstionRuleApplied = 1
			$$$TRACE("  NamedFrequencyNCIDValue Value : "_NamedFrequencyNCIDValue)
		}

		$$$TRACE(" Timed Ncid "_FreqAbstResult.GetData(5)_ "and Value "_FreqAbstResult.GetData(6))

		if ($L(FreqAbstResult.GetData(5)) '= 0) && ($L(FreqAbstResult.GetData(6)) '= 0)
		{
			$$$TRACE(" Checking Timed Ncid Value ")
			// Get value from ORDERS2.FREQUENCY_CONVERSION

			set FreqConversionQuery="select * from "_..DBSchema_".FREQUENCY_CONVERSION where TYPE='Timed' AND NCID=? AND LOWVAL=?" 
			set FreqConversionResult = ..ProcessQueryTwoParam(FreqConversionQuery,FreqAbstResult.GetData(5),FreqAbstResult.GetData(6))

			// Set ConvertTo value from ORDERS2.FREQUENCY_CONVERSION into Named_Frequency_ncid
			if FreqConversionResult.Next()
			{
				if '""=FreqConversionResult.GetData(8)
				{
					set NamedFrequencyNCIDValue = FreqConversionResult.GetData(8)
					set isConverstionRuleApplied = 1
					$$$TRACE("  NamedFrequencyNCIDValue Value : "_NamedFrequencyNCIDValue)
				}
			}
		}

	}

	//Do Conversion Rules - END

	$$$TRACE("  isConverstionRuleApplied : "_isConverstionRuleApplied)



	if (isConvertToText = 1) || (isConverstionRuleApplied = 1) //Scenario 2.1 - One Frequency_Abstract row and has a Named_Frequency_ncid value and can be translated in Cerner
	{
			$$$TRACE("  Processing Scenario 2.1 - can be translated in Cerner")



		// Check For PRN Flag with the current namedfrequencyNCID ( it might be changed if conversionrule is applied else it remains same)
		set FreqTranstQuery="select * from "_..DBSchema_".FREQUENCY_TRANSLATION where NCID=?" 
		set FreqTranstResult = ..ProcessQuery(FreqTranstQuery,FreqAbstResult.GetData(4))


		if FreqTranstResult.Next()
		{
			set PrnFlag = FreqTranstResult.GetData(4)
		}


			//Check if PRN flag rules apply
			$$$TRACE("  PRN flag value : "_PrnFlag)

			if PrnFlag = "Y" // Checking if PRN flag in FREQUENCY_TRANSLATION table is "Y"
			{
				set pResp.ORC07QuantityTiming = "^"_NamedFrequencyNCIDValue_"^^^^PRN" //Create Timing quatity as ‘^’ + Named_Frequency_ncid value + ‘^^^^PRN’
				$$$TRACE("  ORC07QuantityTiming Value : "_pResp.ORC07QuantityTiming)
			}
			else // PRN flag is "N"
			{
				set pResp.ORC07QuantityTiming = "^"_NamedFrequencyNCIDValue  //Create Timing quatity as ‘^’ + Named_Frequency_ncid value
				$$$TRACE("  ORC07QuantityTiming Value : "_pResp.ORC07QuantityTiming)
			}

			//If Named NCID value itself is PRN(1534)
			if FreqAbstResult.GetData(4) = "1534"  //If the Named Frequency is equal to ‘PRN’ (ncid=1534), then change the Named_Frequency_ncid to value 156950 (‘As Directed’) and set the PRN Flag to true.
			{
				$$$TRACE("  Named Frequency NCID value itself is PRN(1534) : "_NamedFrequencyNCIDValue)
				set pResp.ORC07QuantityTiming = "^156950^^^^PRN"
				$$$TRACE("  ORC07QuantityTiming Value : "_pResp.ORC07QuantityTiming)
			}

		return $$$OK // Return - as we got the 	ORC07QuantityTiming value
	}
	else //Scenario 2.2 - One/Many Frequency_Abstract row and cannot be translated in Cerner

	{
		$$$TRACE("  Processing Scenario 2.2 - cannot be translated in Cerner")
