                $$$TRACE(" Start of If")
				 $$$TRACE(" Inside "_FreqAbstResult.GetData(4))
				 $$$TRACE(" Length "_$L(FreqAbstResult.GetData(4)))
				//if FreqAbstResult.GetData(4)> 0 // If Named Frequency not null
				if $L(FreqAbstResult.GetData(4)) '= 0
