				}
				$$$TRACE(" 1")
				if ($L(FreqAbstResult.GetData(13)) '= 0) && ($L(FreqAbstResult.GetData(14)) '= 0) // If How_often_Day_Month_ncid and Day_Of_Month_Value are both not Null
				{
					set FreqText = FreqText_..GetTransalationForNCID(FreqAbstResult.GetData(14))_", "_FreqAbstResult.GetData(13)_" day of the month"_" "
					$$$TRACE("  FreqText value inside Day_Month_ncid : "_FreqText)
				}
				$$$TRACE(" 2")
				if ($L(FreqAbstResult.GetData(4)) = 0) && ($L(FreqAbstResult.GetData(10)) '= 0) && ($L(FreqAbstResult.GetData(12))'= 0) //If Named_Frequency_ncid is null and (Day_of_Week_ncid and How_Often_Day_Week_ncid are not Null)
				{
					set FreqText = FreqText_..GetTransalationForNCID(FreqAbstResult.GetData(12))_" "_..GetTransalationForNCID(FreqAbstResult.GetData(10))_", "
					$$$TRACE("  FreqText value inside Day_of_Week : "_FreqText)
				}
				$$$TRACE(" 3")
				if ($L(FreqAbstResult.GetData(4)) = 0) && ($L(FreqAbstResult.GetData(5))'= 0) //If Timed_Frequency_ncid is Not Null and Named_Frequency_ncid is Null
				{
					set FreqText = FreqText_"Every "_FreqAbstResult.GetData(6)_" "_..GetTransalationForNCID(FreqAbstResult.GetData(5))_", "
					$$$TRACE("  FreqText value inside Timed/Named_Frequency_ncid not null : "_FreqText)
				}
				$$$TRACE(" 4")
				if $L(FreqAbstResult.GetData(7)) '= 0 //If Range_Frequency_ncid is Not Null
				{
					set FreqText = FreqText_"Every "_FreqAbstResult.GetData(8)_" to "_FreqAbstResult.GetData(9)_" "_..GetTransalationForNCID(FreqAbstResult.GetData(7))_", "
					$$$TRACE("  FreqText value inside Range_Frequency_ncid is Not Null : "_FreqText)
				}
				$$$TRACE(" 5")
				if $L(FreqAbstResult.GetData(15)) '= 0 //If Text Frequency is Not Null
				{
					set FreqText = FreqText_" "_FreqAbstResult.GetData(15)_","
					$$$TRACE("  FreqText value inside Text Frequency is Not Null : "_FreqText)
				}

				$$$TRACE(" 6")



                // Increment counter
                set counter = counter + 1

                //Move cursor to next row
               	do FreqAbstResult.Next()
			}

			//After while loop If Freqtext is generated then add "/ Freq: to the Freqtext
			if $L(FreqText) '= 0
			{
				Set FreqText = $EXTRACT(FreqText,0,$L(FreqText)-1) // Removing the extra ","
				set FreqText = "/ Freq: "_FreqText
			}
			$$$TRACE("Final FreqText value : "_FreqText)
			$$$TRACE(" ENd of If")
		}

	}




			//Check the Transalation for Dose units

